// ===== data.js (base): GAME_VERSION, elements, the type chart, reactions, statuses, attributes and class growth =====
// =================== VERSION ===================
// The one public version string. Patch (0.1.x) for fixes and balance, minor (0.x.0) for new systems.
// Save keys (aurelis-wayfarers-v3, its slots, aurelis-meta-v1) and db schemas are separate and never follow this.
const GAME_VERSION=typeof APP_VER!=='undefined'?'Beta v'+APP_VER:'Beta v0.4.5';
const CHANGELOG=[
 ['Beta v0.21.6',['Battle: double tapping or holding a foe\'s HP plate opens that foe\'s card even where another foe stands under the plate.']],
 ['Beta v0.21.5',['World and names: chests open at once again. Places you have explored follow your account, so click to walk works on another device. The Breach Waystone stands in the centre. New journeys leave towns by the west as often as any other side, every town gate has its own signpost, and no town is left without a way out. About a hundred names changed so the same words (hollow, frost, cinder, ember and more) stop repeating: Cinderhollow Deeps is Kilnscar Depths, Hollowmere is Larkspur, Frostgate is Whitehearth, and so on. Saves and bestiary records carry over.']],
 ['Beta v0.21.4',['Battle and roster: every turn opens on the main actions (no remembered submenu). Space, Enter or Z continues past victory, defeat and story screens, and Settings > Controls can bind up to four keys per action. Pets of the Scourges removed in 0.20.9 can be summoned again. Recruited bosses can only be called by Nikaris or a Priest; a summoned Scourge takes the field at full size in place of the three Vanguard heroes, who return unharmed when it leaves. Guardians and Nikaris are tuned down slightly. Skills are learned at 1, 1, 6, 11, 15, 20, 24, 28, 32, 37, 41 and 45, so three by level 10 (nothing already learned is lost). Dual type wayfarers do not turn up for recruitment before the third realm.']],
 ['Beta v0.21.3',['Equipment: the Backpack tab works on phones (a hint card was sitting over it). Upgrade whole party buys every available upgrade in one press. Equipment shows every stat it raises or lowers, and by how much, against what the hero wears. Equip Best and Build party close the Menu when done, with an Undo Equip Best button in Backpack > Equipment. Rarities unlock by realm: Common and Uncommon in the first, then one more per realm. Any piece at +0 now beats the rarity below it at +3, so tempering steps are smaller. The personal quest fight names the real relic reward (weapon, armour or charm) instead of always a weapon.']],
 ['Beta v0.21.2',['Quests and goals: guilds and guild quest progress unlock after the first realm\'s Scourge falls. Personal quests unlock at 50 battles and offer themselves in a pop-up after the fight. The town notice board takes every kind of quest again, guild missions and personal quests included, and the guild notices "Sign the guild ledger" and "First blood in the pit" can be handed in. Next goals stays on screen (it no longer folds or hides when you walk near it), wraps properly on small phones, minimises only by its arrow, and has a Show goals switch in Settings > Display.']],
 ['Beta v0.21.1',['Regular foes are back to their normal size in battle. Heroes and bosses keep the bigger Unified look size.']],
 ['Beta v0.21.0',['Unified look: everything in the world now shares one style. Town roofs have small tile rows and sit lower so they cover less of the screen, battle units are 25% bigger on a crisp backdrop, the hero stays solid under roofs, props and buildings get one dark colour-matched outline and take on their realm\'s tint, and menus use the same frame style with no blur behind them. Settings > Display > Unified look switches it off.']],
 ['Beta v0.20.9',['Bosses are down to 16 Scourges and 4 Calamities, each in its own themed realm (three new realms: Gloamrook Moors, Jademist Highlands, Boneharrow Fields), and the Calamity realms are the grandest. Every town has its own layout and building style per realm. Clouds are a soft cumulus sea again, foes and chests no longer spawn where you cannot walk, and every den, lair and sanctum is entered from the front only. Skills are learned all the way up to level 45. Permanent recruits carry over from every win, with no limit, and a new journey offers a balanced pool of 16 wayfarers (2 per element, 2 per class).']],
 ['Beta v0.20.5',['Grass is back to how it looked before the graphics passes: encounter grass and open ground use the original painting again (no patchwork, extra clumps or tufts spilling over). The newer water, shorelines, wet ground and snow, and land beside exits all stay.']],
['Beta v0.20.4',['Encounter grass reads at a glance again in every realm: dense, varied patches that stand out from plain ground (frost-tipped on snow, dune grass on sand, charred stalks on ash, glowing spore grass in the Breach with no boxy glow). Water has depth: pale shallows, the realm\'s colour, darker deeps, and varied wave marks and highlights instead of a grid of stripes. The aurora spans the whole sky. Every exit walkway has land on both sides.']],
['Beta v0.20.3',['The hero sheet is one page again with a Show dropdown to jump to or filter one section. Tier tags like EPIC are crisp on phones. Next goals stays pinned under the minimap. Taverns offer a mix: no main element twice at a small table, no class twice, at most two of a role. Skills are learned at an even pace: no gap over 6 levels and never three at once, with the kit\'s order kept and old saves keeping what they had.']],
['Beta v0.20.2',['Den mouths, lair and dungeon fronts, caves, the sanctum shrine and its inner door, and the Echo Rift gates now face the camera straight on: symmetric, with a lighter top band, the mouth recessed into the dark, the cast shadow and props kept, and the party still hidden when it walks behind them. The dark slab that used to sit beside every entrance (an outline bug) is gone.']],
['Beta v0.20.1',['Battle fixes: the Momentum bar shows again in every state; the Primed chip stays a small chip in the corner of a foe card instead of stretching over it, and tapping anywhere on a foe card targets it; after a hero uses an item their next turn opens on the main actions; learned-skill lines on the victory screen wrap inside the panel on phones.']],
['Beta v0.20.0',['Light and shadow: every tree, building, cliff and tall prop casts a soft shadow from one sun that swings with the hour, and the HD-2D scene gets a warm key light and a cool fill. Night is no longer a blue wash: lanterns, windows, braziers, torches, waystones and fountains pool warm light on the ground and the rest falls dark; interiors are lit from their fires. Particles per realm (fireflies, pollen, ash and embers, dust, frost sparkle, spores, void motes). Battles open with a shatter in the realm colour, doorways iris on the hero, and a won fight blooms back into the world.']],
['Beta v0.19.9',['Every sprite shares one outline rule (a dark edge in its own darkest tone and a rim light on the lit side). Characters breathe, blink and their hair and cloaks sway; foes idle by family and bosses draw a heavier breath. The battle stage gains a mid-ground of rocks, trees, spires, ruins or shards, a horizon haze and contact shadows. Damage numbers are chunky and coloured by element, crits pop, and reaction text uses the fantasy face.']],
['Beta v0.19.8',['The ground is alive: every field lays its own patchwork of tones with worn paths and clustered grass; grass bites into roads, a wet rim and breathing foam meet the water, cliff tops get a lip of rock; water carries a slow highlight, sparkle and reflections; rain wets the stone and dries after, and snow settles on roofs, ledges and trees and melts away.']],
['Beta v0.19.7',['The battle HUD speaks the same gilded language as the banners and menus: hairline gold rules, small corner ornaments, the fantasy face for the small-caps labels, bevelled tinted plates and matching chips, at the same sizes as before, with a subtle tint from the realm you are in.']],
['Beta v0.19.6',['Every entrance is a solid mass again, the way the old tents were: den mouths, lair fronts, the sanctum shrine and its inner door, and the Echo Rift gates rise above the ground with a lit top, a recessed mouth and a cast shadow, and the party walks behind them and is hidden.']],
['Beta v0.19.5',['World art: den, lair and cave entrances get volume; sanctum side carpets are full panels with their own borders; weather stays put in the world as you walk; pickups are drawn in the world\'s own palette; the Mimic is a chest first, with teeth top and bottom; the walkway out of a field always has ground on both sides.']],
['Beta v0.19.4',['Area titles redone in a fantasy face (also the Victory and Defeat crests and menu headings): the kind word above the name, a rule and colour per place, full width on phones under the minimap, shown only when you arrive, no weather suffix, and "Sanctum: Duskspire" instead of "Sanctum: Duskspire Sanctum". The Breach banner is just its name and its introduction is rewritten.']],
['Beta v0.19.3',['Menus: Back steps from menu to menu and from the first menu closes everything; tabs inside a menu are remembered, not steps. The battle menu remembers each hero\'s last submenu, scroll and skill. Every skill row shows its target, its kind with a symbol (resolved for the weapon in hand), its elements and Primer or Detonator, everywhere skills are listed. New Slash and Pierce symbols. Role names are gone from skill descriptions.']],
['Beta v0.19.2',['Skill kits read right: primers and detonators follow what a skill\'s name says it does, filler skills speak in the class\'s voice, and the Steppe Sniper\'s quarrels swap roles. Fighters\' dual arts are martial moves that name both elements; casters keep their spells. Identity skills are back inside the twelve (Hunter\'s Mark, Cleave, Guard Wall, Purify, Smoke Bomb, Flurry, Flurry of Fists, Meditate, Dissonance, Requiem). Guardians are bosses you can summon: boss-sized, 5 turns for a Priest and 3 for a Monk, with a boss entrance.']],
['Beta v0.19.1',['Every town has its own landmark (an ancient oak, a striped lighthouse, a great lantern and twenty more), named when you arrive and seen from the entry. The phone pad sits under every text box. The Echo Rift hall has no invisible walls, and its gates light up in a colour taken from the boss behind each one. Herbs never spawn on a chest or out of reach. The Breach drops its (relit) tag. Every wayfarer and townsperson has a real stride walking north and south. Wild recruits are spread out (about eight a journey, never two close together, dual types later in the journey). Each realm has its own Scourge instead of a random one. Echoes drop the "the" from their names.']],
['Beta v0.19.0',['Skills and roles reworked. Every wayfarer learns at most 12 class skills (Limit Breaks, bond techs and Archive skills are outside the cap), chosen so each element has a primer and a detonator; dual types prime and set off both their elements with their dual art but never learn the elemental ultimates, which stay with single types. Dual arts hit as physical for fighters (kind from the weapon) and as magic for casters. Focus now raises crit chance by 40% for 3 turns. Skill power follows the class: main-role skills at full strength, sub-role at 80%, off-role at 50% (a priest heals harder than a bard, a thief debuffs harder than a mage), and a nature lifts the skills of its own role. Bosses eased a little (about 7% HP) to keep the journey at the same pace. The tavern now shows which recruit brings the primer or detonator your party lacks.']],
['Beta v0.18.9',['You can change your party in the Echo Rift hall between gates. Heroes outside the six keep no gear: everything goes back to the pack when they leave, pick-ups are suggested only for the party, and a bare hero joining is offered Equip Best. New Game+ sends you to realms you have not seen and bosses you have not faced first; once everything is seen the mix is random with a lean toward bosses missing from your last two journeys.']],
['Beta v0.18.8',['Records opens on Completion: every tracker each realm has (fields, Den, Lair, Sanctum, beacon, quests, bounties, taming, and the realm\'s Echo once the Rift is open), with an Echo Rift section above it that keeps a secret boss as ??? until beaten. Account play time now counts the same thing each journey counts, raised to at least what your save slots add up to. The Notice Board is one list again (quests, bounties, guild missions, notices) with one Accept all and one Claim all that says what must be handed in elsewhere. Settings > Tips no longer breaks into single letters on phones. Den, Lair and Sanctum tags show on every arrival, and the Meridian Breach introduces itself the first time.']],
['Beta v0.18.7',['Phones run cooler on High graphics: the world and battle no longer redraw on every screen refresh while nothing moves (30 frames a second at rest, 8 under a menu, none when the app is hidden), and phones cap the internal render at 2 pixels per art pixel unless you pick 3x in Settings. Nothing changes at rest in how it looks.']],
['Beta v0.18.6',['The Meridian Breach now gets the same path check as every other map when it is laid out, so a chest or roamer can no longer land where no path reaches it.']],
['Beta v0.18.5',['Computer screens: the world view fills the window with no dark bars (on wide windows the whole frame grows so you see more world), menus taller than the window now scroll inside themselves instead of needing the page behind them scrolled, and the world and battle screens never scroll the page. This also fixes the Windows app, whose older browser kept menus and the view at the unzoomed size. The barred hoard no longer sits in Next goals after the Calamity falls (it stays in Quests).']],
['Beta v0.18.4',['Menus remember where you came from: Back, Esc, the gamepad B button and the Android back gesture return to the last view with its scroll position instead of leaving the menu. Tapping outside a menu closes it (never for popups that need an answer). Settings > Account and Saves and the Journey tab can load another save slot in game, with a confirm that names the unsaved time. Settings is reorganised into Play, Display, Sound, Controls, Account and Saves, Help and Feedback, and Danger zone, folded into categories on phones.']],
['Beta v0.18.3',['Click to move on a computer no longer wanders off to a random spot: a mouse press only turns into a drag after real movement, the tapped tile is read when you let go, and the Windows app no longer mixes zoomed and unzoomed coordinates. Skill lists show their numbers permanently: a fixed strip with the damage estimate in battle (power elsewhere), hits, kind and MP cost, instead of a number that popped up and faded.']],
['Beta v0.18.2',['The Meridian Breach has its own look apart from the realms: cracked near-black violet ground with teal veins, a star sea with slow aurora bands and drifting shards, pale glowing cliffs, rift-glass bridges, obsidian rune stones and spore bushes. Fights that start in the Breach get their own backdrop of broken islands under the aurora instead of the last field you walked.']],
['Beta v0.18.1',['Battle animation pass two: every status has its own shape (poison bubbles, bleed streaks, stun stars, ward plates and so on), all twelve Limit Breaks and the signature skills have their own flourish, boss windups and realm gimmicks telegraph before they land, slash arcs are thicker with a glow, spell flashes tint by element, multi-hit counts only blows that landed, big hits get a short hit-stop and camera punch, and foes fall apart differently by the kind of blow that finished them.']],
['Beta v0.18.0',['Foe and boss sprites on the battle stage are repainted at a clean whole-pixel scale (bosses one and a half times their art, guardians twice, with the HD paint they had lost), with room around them so arms, hammers, crowns and tails are no longer cut flat, feet on the stage line, and a gentler boss idle glow. Bosses stand about 90 px tall now.']],
 ['Beta v0.17.9',['Wide windows (desktop, the Windows app) use up to 1400 px of width instead of 1000, so the world view shows more and the dark side margins shrink.',
  'Battle animation overhaul: every skill now shows its kind. Slashes arc with an afterimage, blunt blows land with a ground shock ring, dust and a thump, piercing thrusts drive a bright line, ranged skills fire a projectile with a trail, multi-hits repeat with a count, each element casts its own delivery (fireball, ice shard, gust, water drop and splash, ground crack and spikes, light pillar, lightning bolt, gathering void), heals bloom upward, buffs ring upward and debuffs drip downward, songs send notes, Limit Breaks go one and a half times bigger with a stage flash. Heroes swing, smash, thrust, shoot, cast, pray or cheer to match, and foes jolt, squash, jab back or flash with the element they take. All-foe physical skills no longer share one spin.']],
 ['Beta v0.17.8',['The Echo Rift is concentric: the Echoforge at the centre, the five Calamity gates in a ring around it, and the twenty Scourge gates in a wider ring around those, four to an element with a sign per arc, the lane from the south door running through both rings to the forge and the Riftkeeper at the north end.',
  'An Echo in the Rift fights alone: nothing it would summon joins the fight, and everything in a rift fight is level 55.']],
 ['Beta v0.17.7',['The hero sheet is a tabbed sheet: a compact header (portrait, name, class and level, role, elements, HP, MP, XP, Equip), then Overview, Stats, Skills (with a filter), Gear and Role tabs; the last tab is remembered and the body scrolls inside the box. Menus clear the system bar and scroll within themselves.',
  'Wide screens: the battle puts the Foes in the right column under the Rearguard, one card per row, and the command menu keeps the full width under the stage. The "Guard against a big hit" goal also counts a Guard in any boss or elite fight.']],
 ['Beta v0.17.6',['Battle rebalance, damage kinds. No class reaches more than two physical kinds through its own skills and weapons (Warrior and Knight slash and blunt, Monk blunt and slash, Thief slash and piercing, Archer and Sniper ranged and piercing, Druid ranged and slash; casters magic), so a party has to mix classes to answer slash, blunt, piercing, ranged and magic. The weapon sets the kind of physical skills: a warhammer or mace hits blunt, a sword slashes, a lance in a knight\'s hands is blunt, thrown stars pierce. The Skills list says "Blunt with your mace" or "Always Blunt" under each skill, and a foe\'s Weak tooltip lists which of your heroes answer it. Hand Axe is now Heave and Javelin is Shield Throw. Flying foes take a little more from piercing. Pacing is unchanged (about 12.6 boss tries, level 41 at the end).',
  'Render resolution follows your display. On a 1080p or larger screen, a phone at 3x density, or a zoomed window, the HD-2D view, the light map and the battle stage render at 2x (3x on High at 1440p and up) instead of one internal pixel per art pixel, characters are sampled at the finer density, and ground, props and buildings are upscaled once with a pixel-art scaler, so edges and diagonals stay crisp instead of blurring. Settings has a Render scale row (Auto, 1x, 2x, 3x); Auto steps down by itself on hardware that cannot hold the frame rate. The Flat view picks whole device pixels per art pixel. A true art-level overhaul (native 2x tiles, props, icons) is a later step.']],
 ['Beta v0.17.5',['The Loadouts tab lists each loadout with its vanguard and rearguard (portraits and names) and a Load button.']],
 ['Beta v0.17.4',['Make camp lets you choose Camp Supplies or a Tent (counts shown, the Tent also gets KO\'d heroes up), and picks the Tent by itself when you have no Supplies.']],
 ['Beta v0.17.3',['Menus and sheets always fit above the browser bar and scroll inside their own box (the bottom of a long sheet was reachable only after scrolling the page behind).']],
 ['Beta v0.17.2',['Walking: every wayfarer in a robe now strides properly (near leg forward, hem trailing and lifting over the stepping boot, one boot raised in the front and back frames), and a long-standing bug that left about twenty-six wayfarers with no boot colour at all (their feet vanished) is fixed. The stopgap sway from 0.15.7 is gone with it.']],
 ['Beta v0.17.1',['The Echo Sanctum is now The Echo Rift, rebuilt around the Echoforge: the forge stands in the middle of a 33x28 hall, the five Calamity gates ring it, the twenty Scourge gates sit in five named bays along the walls (grouped by element, with braziers and signs), and the Riftkeeper and his gate hold the north end on the axis.',
  'At the level cap, experience becomes gold (8 XP to the gold), and a drop you already hold fifty of is sold on the spot; both show on the rewards screen. The Pork Chop Sandwich has a shorter description. The Role row in the sheet fills its line. The "Copy hero seal" button is gone until co-op exists.',
  'A bonded pair\'s bond grows after a battle as long as both are in the party (vanguard or rearguard), not only when both stood in the vanguard. Skill descriptions no longer carry the sub-role note. The sheet\'s Equipment section uses the same gear rows as the Equipment page (icon, tier frame, chip, stats). Legendary classes are not named in class lists until one of their heroes is unlocked.']],
 ['Beta v0.17.0',['Echo Rift: a gate you beat lights up at once in HD-2D too (its cached frames did not know about the win), and the Echoforge has moved to the right side of the hall so it no longer stands between you and the Riftkeeper\'s gate.']],
 ['Beta v0.16.9',['Battle: bosses and guardians are drawn a third larger on the stage and ordinary foes a tenth larger, with their plates, intents and tap areas following. The HP and MP bars under "<Hero>\'s turn" in the action menu are gone. Double tap a foe, or press and hold it, to open its card.']],
 ['Beta v0.16.8',['Echoforged gear is the best in the game short of a personal relic: every piece sits 14% or more above the shop\'s tier-5 piece at max temper in every stat, cannot be tempered (it starts where tempering would end), and relics stay above it. The Echoforge now has a recipe for every weapon family and for mail, robe and vest, and asks 1.6x the tier-5 shop price in gold on top of the shards.',
  'The Echoforge in the Sanctum hall is a landmark: a stone plinth with the anvil, an echo-crystal brazier, a banner, a rune ring and drifting shards, lit in both views.']],
 ['Beta v0.16.7',['Echo Rift gates glow for this journey\'s wins only (the Codex keeps the account record). The Riftkeeper tells you that breaking every Echo opens the centre gate, and warns about what waits there.',
  'The "Guard against a big hit" goal counts any Guard made while a foe winds up or telegraphs, so it no longer sits unfinished at the end of the game.',
  'Forge and Tempering rows carry the item\'s rarity colour like the shop; the Temper button is plain again (the cost chips stay under the title).',
  'Walking left or right bobs a pixel on the stride, so nobody glides.']],
 ['Beta v0.16.6',['Materials have their own icons (every ore, log, herb and part looks different, and every guardian shard too), and gather nodes in the field show the material they hold: ore glinting on a rock, a stack of logs, the herb\'s own plant, in both views. A herb node now yields exactly the herb it shows.',
  'Selling: Alchemy buys back potions, tonics, cures and travel gear (40% of list) alongside the spare gear, materials and charms the Sell tabs already took; tempered gear returns part of its tempering cost; rare, tempered and Echoforged pieces ask before selling; keepsakes (personal relics, bound, legend, signature and Medal gear, the Stick) cannot be sold.',
  'Crafting: forging makes the +0 piece, priced so gold plus counter-bought materials come to 85% of the shop price (it was 72% for a +1 piece).',
  'Upgrades think in tempering: a purchase or forge counts as an upgrade when the piece at max temper beats what you wear at max temper, and the shop tags, Tempering rows and Upgrade popup say so ("+24 ATK at max temper"). Equip best still equips by current stats and lists pack pieces worth tempering. The Tempering rows show the gold and materials under the title and the button reads "Temper · Ng".',
  'Personal quest relics are best in slot for their hero: the top piece of the hero\'s preferred weapon or armour family at the current realm\'s tier, fully tempered, with the relic\'s own edge, and they refresh as you progress.']],
 ['Beta v0.16.5',['Reactions show one marker: the banner, which now carries the MP returned to the detonator (the separate floating text is gone; the target tag still previews the reaction before you hit).',
  'HD-2D overworld: monsters, bosses and the Riftkeeper keep their full size; only walkers took the smaller scale of 0.15.8.',
  'Echo Rift gates: colour always means beaten. An open gate you have not won stays grey (runes included); a won gate glows in its element and keeps its gold pip. Echoes that change form mid fight now light their gate when beaten. The record is per account, so a gate won in an earlier journey glows too.']],
 ['Beta v0.16.4',['Arena: every tier shows how many times you have cleared it and your best score (waves, turns, KOs and the health you kept), a medal sits beside the title once you have won it, and the rewards screen shows the run\'s score against your best. Journey records count your arena medals.',
  'The Daily Trial is now the Weekly Trial: the same trial and twist last from Monday to Sunday, with your best for the week kept and the leaderboard per week.']],
 ['Beta v0.16.3',['Fields whose road bends north or south after the sealed gate no longer keep an open lane running east past the bend; the only way on is the road to the next town.']],
 ['Beta v0.16.2',['Toasts sit a little above the bottom button row instead of in the middle of the screen.']],
 ['Beta v0.16.1',['House doors are back to their old size (the tall ones looked out of place). Toasts appear in the upper middle of the screen, clear of the buttons. Hints stay up 30 seconds.',
  'Battle: Start/Stop auto, Pause and Speed work while actions play (a timed-hit ring no longer swallows the press). Target name tags are no longer cut off. After an arena fight the results return you to the Guild Hall\'s arena page.',
  'Guild and arena quests are handed in at a Guild Hall only, never from the Menu. The Training team only takes wayfarers three or more levels below your top one (plus the anchors it needs); the other slots go to your strongest, not to whoever merely has levels left. The Eclipse Gauntlet recommends level 50, the cap.',
  'Battle side view, second pass: heads re-derived from the front view (same eye row and size, same hairline and hat, a true three-quarter face), long hair behind the shoulder, glasses, tusks and earrings on the new face, eyes in the helm visor.']],
 ['Beta v0.16.0',['Battle sprites: the side view is now a three-quarter profile. Nose, lip, chin and ear, a clear near eye with iris and catchlight and a hinted far eye, hair and hats keeping their front-view shapes, a wider torso with a shaded far side, and the head set back so staffs and bows no longer cross the face. Every wayfarer reads at battle size again.']],
 ['Beta v0.15.9',['Roster and reserve cards show each wayfarer from the front (the side sprite stays for battle and the Codex).']],
 ['Beta v0.15.8',['Overworld scale: in HD-2D every character (wayfarers, townsfolk, roamers) stands a sixth smaller against the world, and house doors are taller wherever the wall can hold them, so a wayfarer now stands about door high instead of over it. The sprites keep their detail: they are sampled at twice the texel density.']],
 ['Beta v0.15.7',['Graphics sweep, part two. Den mouths, Lair fronts and Sanctum gates are lit from the upper left like the sprites: five-step ramps, mortar and brick tones, outlines in the colour they border, a cast shadow on the ground, glow round embers and crystals, and the hero no longer dithers through the entrance in HD-2D.',
  'World props got the same treatment: stalls with folded awnings and planked counters, a fountain with rippling three-tone water, lamps with glass heads, barrels, crates, hay, carts, banners, anvils, braziers, signs, the notice board, fences, boats, stones, ruins, tents and the town landmarks all have lit and shaded faces, outlines and base shadows.',
  'Overworld walkers are back at .8 of the rig (at .9 they stood taller than the doors again); battle sprites stay at .9. Walking north or south animates again: the body sways and bobs on the stride frames, which a robe used to hide.']],
 ['Beta v0.15.6',['Graphics sweep, part one. The HD-2D camera is back where it was before 0.15.3 (the zoomed world looked worse). Wayfarers are drawn at .9 of the full rig in the overworld and in battle (36x50), the middle between the full rig that stood too tall and the .8 and .85 that went soft. Part two (depth on entrances and world props) follows.']],
 ['Beta v0.15.5',['Portraits are proper busts: the front view of each wayfarer from the hat to the shoulders, both eyes showing, on party cards, battle cards and the command head (they used to be a crop of the side sprite that cut the face at the chin).',
  'The Meridian Breach: most of every island is tall grass now (it is a training ground), the Breach turns to match the way you walked through the seal (a seal walked north lands you on the Breach\'s south edge, walking north), and coming back from the Breach lands you on the open gate tile, so you can step straight back in. That fixes the field you could not re-enter the Breach from.']],
 ['Beta v0.15.4',['Battle: the vanguard\'s floating plates on the stage now show an MP bar under the HP bar.',
  'The Meridian Breach is its own place: islands of broken ground afloat in the void sea, joined by bridges, with the Breach Waystone in a ring of standing stones at the heart and a landmark from each realm you crossed on the outer islands. The broken seal still lets you in from the west, and the grass hides the fights.']],
 ['Beta v0.15.3',['HD-2D world: the camera sits a fifth closer, so houses, doors, trees and tents fill more of the screen, while every character keeps the size it had. Wayfarers now stand about door high instead of towering over the street. Character cards are sampled at twice the detail to make up for the smaller card.']],
 ['Beta v0.15.2',['Sanctums rebuilt inside: one symmetric temple on a single axis with a straight carpet from the door to the guardian, and the whole hall turns to face the way you walked in.',
  'Sanctum gates are a proper facade now instead of a bare gate, and Den mouths and Lair entrances are themed to the realm they sit in and to what lives inside, in both the 2D and HD views.']],
 ['Beta v0.15.1',['The Echo Warden is the Riftkeeper, and is called that in both forms. Rift Echoes are level 55. Once every Echo has been beaten he leaves his post and the middle gate opens; step through and he takes on the power of the rifts before your eyes, then the fight begins. Beaten, he returns to his spot in a new look, still offering the free rest, and the gate lets you rematch him any time.',
  'The Meridian Breach can be walked to: when the Calamity falls, the broken seal at the end of its realm\'s field opens onto the Breach, and the Breach\'s west gate leads back the same way. The Waystone still lists it.',
  'Sprites: battle heroes a touch smaller (level with the taller foes), overworld walkers a touch bigger so their faces and gear read again.']],
 ['Beta v0.15.0',['Overworld: the player, townsfolk and other walkers are drawn with a compact version of the new hero rig (about 30 px tall, drawn at the smaller geometry, not shrunk) so they stand at door-lintel height beside tents and lamp posts again. Battle sprites, poses, portraits and the Bestiary keep the big rig.']],
 ['Beta v0.14.9',['Wayfarers rebuilt from the ground up: a new hero rig about six heads tall (the figures were four) with a real skull, neck, shoulders, waist, knees and boots, drawn from shaded tubes and polygons like the bosses. Every class reads in silhouette: knights in plate with pauldrons, tabard and shield, warriors in plate and leather with greaves, mages in flared robes with bell sleeves, archers in tunics with quiver and strap, thieves hooded, monks bare-armed with wraps, priests in robes with a stole. All thirteen hair styles redrawn with volume and a parting, every hat refitted, faces with catchlit eyes, brows, nose and mouth, and the beards, scars, masks and paint that make each hero theirs. Front and back views share the rig, the stride swings the arms, the battle poses and the townsfolk props were ported to it, and portraits show the head and shoulders.']],
 ['Beta v0.14.8',['Party cards: the Sheet and Equip buttons sit in their own row under the bars on every screen size (they overlapped the bars on an open Galaxy Fold). Equipment: the pet is a slot like the weapon, armor and charm, tap it to choose, change or remove the pet, with no extra buttons; the per-hero Auto button wraps under the slots on phones instead of being cut off at the edge.']],
 ['Beta v0.14.7',['Wayfarers, pass one: every hero gets a real face (2x2 eyes with a highlight, brows, a mouth, nose and jaw shade), a neck, two-tone cloth and trousers lit from the left, sleeves that separate from the torso, hair with a sheen and a parting, knees and boot cuffs, steel glints, blades with a bright edge and a dark bevel, wrapped hafts, quivers on archers, and a 1px head bob on the stride. Portraits use the same sprite, so they read better too. A deeper rebuild of the body proportions follows.']],
 ['Beta v0.14.6',['Party cards have an Equip button beside Sheet: it opens Backpack > Equipment with that hero\'s row scrolled into view and lit.']],
 ['Beta v0.14.5',['Menu on phones: the seven group tabs sit four and three across two even rows instead of leaving Settings alone on a row of its own.']],
 ['Beta v0.14.4',['Sanctums are sacred places that belong to their land now. Outside: a stone shrine gate with two pillars and a stepped lintel, prayer ribbons and a bronze bell, a worn stair up to a door of light, two stone lanterns that glow at dusk, and a ring of lighter ground with a path of flat stones; moss and flowers, salt and kelp, ember cracks, snow and icicles, gilt or star dust on the stone by realm. Inside: pale bone and warm-grey stone with the realm\'s accent instead of crimson, carved columns, hanging prayer cloths, stained-glass windows with light on the floor, a cloister garden in the courtyard (flower beds, a raked gravel garden, stepping stones), stone lanterns, and a hall with a long runner carpet and candles up to the rune circle, with golden motes in the air and a calm new Sanctum theme (harp, choir and organ).']],
 ['Beta v0.14.3',['Void realms (The Ashen Expanse, Wick\'s End and the other dark lands): the sky past the edge of the map is a star-dark void now instead of pale grey cloud, in both views; on tall phone screens stars twinkle over the band above the map.']],
 ['Beta v0.14.2',['Four more Scourges, twenty in all: The Hollow Shepherd (earth and light, hides in lantern fog until a Scan or a Light skill finds it), The Pale Weaver (ice and lightning, a spider whose webs snare and root), The Crow Regent (wind and shadow, takes a second form at half health) and The Geyser Matron (fire and water, rising steam that Water skills ride and an Earth skill dams). Twenty-five bosses, twenty-five Echoes.',
  'The Echo Sanctum has 25 gates: two rows of Scourge gates along the north wall and the five Calamity arches in a free row in the middle of the hall, all fully visible, none against the south wall where the walls used to hide them.',
  'Every boss redrawn from the ground up: all twenty Scourges, the five Calamities and the Riftkeeper have new 60x60 sprites with real silhouettes, three materials lit from the top left and a part that moves on idle (the Thornback Warden is a hulking thorn-bark treant with a bramble crown and a glowing sap heart; the Maelstrom Drake a coiled sea serpent with a storm crest and lightning in its jaws; the Cinderking a slag colossus with a furnace chest; the Hoarwyrm a glass-winged frost wyrm, and so on). The Bestiary, the lairs and the battles all show them.']],
 ['Beta v0.14.1',['The Meridian Breach: after the Calamity falls, every Waystone can take you to a field where all the realms you crossed bleed through. Its foes come from every one of those realms at your strongest hero\'s level plus two (up to the cap of 50), tougher than usual, with Breach elites in one fight in five; every win pays extra gold and sometimes top-tier materials or an Epic or Heroic charm. Auto battle works there, so it is the place to bring a party to level 50.',
  'Dens and Sanctums: the miniboss no longer wakes when you open the chest. It waits at the end, at the back of the den or on the rune circle of the keep, like a Scourge in its lair; walk up to it and fight. The prize chest stays shut until it falls.',
  'Fixed: a bounty beast or legend challenger could be placed inside the Sanctum gatehouse or a den mouth on the field, where nobody could reach or talk to it. They now stand on open ground, and a challenger always answers.',
  'Heroes: eye patches were on a quarter of the roster; now a handful keep them, and a third of the scarves and earrings are gone, so each mark stays distinct.',
  'Animations say what the skill did: all-foe physical skills spin the hero through a full turn with slashes on every foe; big spells (every-foe or very powerful) throw rays from the caster, a ring and an element flourish on every target (bolts, gusts, fire rays, water and ice rings) and shake the screen; party-wide heals and buffs ring every ally with rising motes; songs ring three times around the singer.']],
 ['Beta v0.14.0',['Townsfolk: every service NPC has a silhouette and a prop you can read at a glance (innkeeper with a tray and keys, smith with a leather apron and hammer, alchemist in a long coat with goggles and a vial, guild clerk with a ledger and quill, tavern keeper with a mug, archivist with spectacles and a book, beastwarden with a fur collar and a pup on a leash, guards in helm with spear and shield, priests with a censer, shepherds, fishers, farmers, miners, pickers, lamplighters, stooped elders with a cane, small children). Cloth is quieter so the props and faces read, every garment is lit from the left, the walk cycle swings the arms and bobs, and a standing villager breathes on two frames.']],
 ['Beta v0.13.9',['Sprites, family 4: the last eleven foe families are redrawn with idle, attack and hit frames: gust imp, snow harpy, yeti, stormling, gargoyle, voidspawn, star eater, mimic (the lid gapes on the bite), drowned sailor (an anchor), rime wight (a frost blade) and gale phantom (a war horn), plus 22 of their variants with their own shapes. Every foe in the game now animates.']],
 ['Beta v0.13.8',['Heroes move the way they fight: every hero has real battle poses now, picked by the skill. Slashes swing the weapon over the head, piercing strikes thrust with the body leaning in, blunt blows smash two-handed, bows and crossbows draw and release, spells raise a hand with an orb in the element\'s colour, heals and revives are a prayer with hands together, Guard crouches behind the shield or the weapon, buffs raise the weapon in a cheer, and a hit flinches. Idle breathes on two frames.',
  'Sprites, family 3: slag golem, ice knight, husk guard and the barrow bones redrawn tall and plated with a glowing core or visor, idle, attack and hit frames, and nine of their realm, mini-boss and Sanctum variants get their own shapes (turbans, horns, crests, kelp, flames, a censer, a crown, skulls).',
  'Balance: the Brinehag Matriarch was far harder than the other Scourges in the sims; her HP, magic and resistance come down and her hexes hit a little softer. The Ironmaw Tortoise was the easiest and bites a little harder.']],
 ['Beta v0.13.7',['Four new Scourges: The Locust Choir (a swarm, wind and earth, its Brood Cloud bursts under heavy blows), Ironmaw Tortoise (armored, earth and water, its Shell Lock cracks to Lightning or Ice), Candleking Moth (a fire and light flyer whose flame marks your strongest hero) and Brinehag Matriarch (water and shadow, calls the drowned unless you break her shield). Any of the sixteen Scourges can now sit in any standard realm.',
  'A fifth Calamity, The Hollow Sun (light and fire, its Corona Ring swaps between spells and weapons every four turns), in a new Calamity realm: The Ashglass Reach, a scorched salt flat with the town of Saltwick and The Glass Cathedral, its own foes, weather, quests and Lore chapter.',
  'The Echo Sanctum has 21 gates now (two rows of Scourges, five Calamity arches on the south wall) and the Riftkeeper opens once all 21 Echoes are beaten. Journeys already under way keep their drawn realms and bosses.']],
 ['Beta v0.13.6',['Roles: eight of them now, Striker, Marksman, Caster, Guardian, Healer, Support, Saboteur and Summoner. Every class has a main role and two sub roles (Warrior Striker/Guardian/Saboteur, Knight Guardian/Striker/Support, Archer Marksman/Saboteur/Striker, Thief Saboteur/Striker/Marksman, Monk Striker/Healer/Support, Mage Caster/Saboteur/Support, Priest Healer/Summoner/Support, Bard Support/Caster/Healer). Sub role skills run at 85% power.',
  'Main role swap: from the hero sheet in town you can lead with a sub role instead. Its skills go to full power, the class role\'s drop to 85%, and auto-spent stat points follow the new role. The sheet names the weapon family that suits each role.',
  'Faith matters: summoned guardians hit harder with the caller\'s Faith, Light and Shadow damage gain a little per point, and heroes sometimes shrug off ailments by Faith.',
  'Armored foes are weak to Blunt blows (and Magic) and resist Slash, Piercing and Ranged, as the type chart says. One free stat reset for every journey, old saves included.',
  'Sprites, family 2: gull, thunderhawk, cave bat, cloud ray, tide wisp, brine jelly, ash wraith and eclipse wraith redrawn with idle, attack and hit frames (flyers show both wings, rays undulate, wisps and wraiths have a glowing core and trailing tendrils, wraiths carry a lantern or a scythe), and 22 of their realm, night, Sanctum and mini-boss variants get their own shapes.']],
 ['Beta v0.13.5',['Charms above Rare: six Epic and four Heroic charms. Alchemy sells Epic from the third realm and Heroic from the fifth, both have recipes (Dread Cores and tiered materials), later bounties sometimes post one, the first fall of an Echo may leave one, and the top two arena tiers add one to their purse now and then.',
  'Healing light burns the undead harder: a heal on an undead foe now deals 135% of its amount (party-wide heals 100%), revives count as strong heals, and Light weakness adds on top. It beats a plain hit by a wide margin.',
  'Battle: a hero with six or more skills gets filter chips over the Skills list (Damage, Heal, Buff, Debuff, Prime, Detonate, and the damage kinds); the pick is kept for the fight.',
  'Records > Lore is a world book: seven chapters on Aurelis (the Meridian and the dark, Scourges and Calamities, Echoes and the Sanctum, the wayfarers and their guilds, customs of the road, beasts and taming, the elements) and a chapter per realm you have reached with its history, customs, a saying and the lore you heard there. The element chart, weather and rare skies live under Guides > Charts.']],
 ['Beta v0.13.4',['The arena is the Guild Hall\'s: enter it only there (the Menu\'s Arena tab just reads). It is now the place to farm gold and rare materials: every tier pays its purse again on every win, with tiered ore, wood and herbs, and from the Golden Coliseum up Dread Cores, Wisp Ichor and Golem Grit.',
  'A seventh guild, the Pit Masters: standing from arena wins (more for higher tiers), perks for a bigger arena purse and an extra material, a Pit counter (Dread Cores, relic bundles, Elixirs), the Pitmark Charm, Champion\'s Belt and the title Pit Master. Five missions.',
  'The Guild Hall\'s Guilds tab opens with a Guild shop section: every counter you have unlocked, with buy buttons, and the rank that opens the others.']],
 ['Beta v0.13.3',['Menu: the World group is now Map (the area map with a World map button); Records opens on the Realms tracker (per realm: quests, bounties, Den, Sanctum, boss) and the account stats live under Journey; element strips on every party card and reserve mini, single types too; the Bonds tab only lists pairs you can work on.',
  'Smithy and Alchemy: Upgrade whole party tempers to the highest forge level and per slot "best upgrade" now chains buy and temper steps; anything out of reach shows a "What I need" popup (gold, materials, where to get them) from the goal line and the Out of reach rows; upgrades under 3% are not suggested.',
  'Battle: Invoke, Spirit Call and the pet are one Summon command (a chooser when there is more than one); phones: the commands come first again and the skills list scrolls to its end.',
  'Towns: "!" over NPCs who have a quest for you; tamed beasts get unique names; the Echoforge is an anvil inside the Echo Rift (no Smithy tab in town); beaten Echo gates glow in their element colour, Calamity gates are taller crimson and gold arches.',
  'The Riftkeeper: an ultimate boss behind a sealed gate in the Sanctum, open once all 16 Echoes are beaten: level 60, cycles through the eight elements, raises Echo shades at 40% HP and winds up an Unmaking that only Guard survives. First win: the Riftkeeper charm (+10% every element, MP costs +10%), the Riftwalker title and a New Game+ Rift modifier. The Echo Warden now offers a free full rest.',
  'Sprites: the first foe families are redrawn with real animation frames (idle A/B, attack lunge, hit flinch): mossling, dewtoad, cinderpup, frostwolf, crawler, shellguard, magmaslime and the gnat swarm, plus 21 realm, night and boss variants with their own shapes (horns, crowns, fins, collars), not recolours.',
  'Tents (Last Ember, Wick\'s End and camps) are no longer flat triangles: lit and shaded faces, cloth panels, a sagging hem, guy ropes and a base shadow; in HD-2D they stand as round cones instead of upright cards.']],
 ['Beta v0.13.2',['Guild rank 1 no longer adds battle XP for everyone from the first fight (the Beastwardens, Archivists and Steady Hand rank 1 perk is a 3% inn discount instead); XP perks start at rank 2. The Guilds page text matches.']],
 ['Beta v0.13.0',['Fix: on phones the battle stage frame no longer clips the bottom 8 pixels of the stage, so labels under the heroes have their room back and stop crowding the foes.']],
 ['Beta v0.12.9',['Sprites and effects: every wayfarer now has their own look on top of class and element (hair style and colour, skin tone, one or two accessories such as a scarf, eyepatch, satchel, shoulder plate or circlet, and a tinted weapon), in the overworld, in battle and on portraits; legends keep their hand made looks. Skills show their element as a shape, not just a colour: flame tongues, a wave arc, an ice shard fan, a jagged bolt, bursting rock, curved wind slashes, a light beam, a shadow burst; physical hits show a slash, pierce, impact or arrow; heals, buffs and debuffs have their own marks; Limit Breaks flash the screen (a still tint under reduced motion). Bosses and guardians breathe, and a foe winding up a big hit swells and glows.']],
 ['Beta v0.12.8',['Effects pass, first slice: new battle effect shapes and boss art frames are landing (more in the next updates).']],
 ['Beta v0.12.7',['Battle on phones: your heroes\' cards (HP, MP, turn marker) sit right under the stage with the commands below them, so nothing falls off the bottom of the screen.']],
 ['Beta v0.12.6',['The main menu is grouped by what you do: Party (Party, Roster, Loadouts, Pets and a new Bonds tab), Backpack (Equipment, Items, Materials), Quests (Quests, Bounties, Guilds, Arena, in the order of the board and the hall), World (Map, Journey), Records (Bestiary, Codex, Lore, Music Room), Guides and Settings.']],
 ['Beta v0.12.5',['Open Sanctums are lit by the sky in HD-2D too: time of day, dusk and dawn tints and the weather reach in, lamps dim by day, and a guardian fight inside one happens under that weather. Closed Sanctums, lairs and Dens stay indoors.']],
 ['Beta v0.12.4',['Fix: in the first realm the Bonds screen says again when bonds open, instead of listing locked pairs.']],
 ['Beta v0.12.3',['Sanctums look sacred: the field entrance is a shrine with a stair, pillars, a glowing rune arch, lanterns and a ring of stones, in 2D and HD-2D. Inside (new journeys), the guardian stands on a rune circle ringed by pillars and braziers, visible before the fight with its name on approach. Guardians are Scourge-sized in battle, and no two Sanctums or Dens in a journey share one; the Priest\'s Invoke summon stays smaller. New towns keep the three tiles in front of every exit clear of buildings and tall decor.']],
 ['Beta v0.12.2',['Fix: Camp Supplies make camp again (they were treated as a Tent since 0.11.4). The Bonds screen shows each pair\'s wins-together goal and bar again next to what the next level unlocks.']],
 ['Beta v0.12.1',['Hints: queued tips show in the order they came up (core battle tips still go first early on), and the battle tip card stays small (its Log button lives on the world card and in Settings).']],
 ['Beta v0.12.0',['Bonds: fifteen new bonded pairs, each with a joint tech and two talks; every pair now has an after-the-battle talk (level 3, once a Scourge or the Calamity falls with both in the Vanguard) and the new pairs talk at camp and at the Inn (level 2). The Bonds screen lists every pair, its level, what the next level unlocks and every scene with a Watch button. Companions are now Pets: a Pet slot sits under each hero\'s gear in the Equipment menu and on the hero sheet, with a picker, and Equip best pairs free pets too.']],
 ['Beta v0.11.9',['Quests: a quest or bounty you accept from now on is handed in at the Notice Board that posted it, and guild missions at any Guild Hall; a beaten bounty\'s reward waits at the board. Quests taken before this update still claim anywhere. Quest targets show on the field map before you reach them, and towns with a reward waiting say so on the world map. The Guild Hall gets its own "!" marker. Next goals lists your active quests under the main quest, and tapping any goal opens a step by step guide. Hints come slower early on, core battle tips first, and every tip you have seen is kept in a Hint log (Settings > Tips). Guilds have five ranks again, one perk each. New journeys draw their realms in rising order of strangeness. World: no weather inside lairs and Dens (some Sanctums are open to the sky), roaming foes are a little stronger than random ones, chests and drops can hold bandages, ash and tents, and new towns keep the Notice Board and waystone apart with nothing in front of them.']],
 ['Beta v0.11.8',['Party and gear: Build Party now weighs element coverage properly and dislikes doubled elements; Fresh mix favours heroes who have not fought lately. Equip best weighs each hero\'s main role and gives the same loadout every time (ties no longer follow the pack order). The Smithy\'s Upgrade whole party looks at where a piece can end up: it buys or forges the base and tempers it as far as your gold and materials allow, picking the best final stats; Alchemy gets the same button for charms. Battle: party MP shows on every hero card, the single target preview is no longer cut off, a new Settings option fires single target skills at once when only one target exists, Guard lights up only when a foe will really hit before your next turn, and a guarded hit fills some Limit. Heroes: the Epic tag and the purple border always agree, Epic is a hand picked set (dual and single types, never a starter), and dual types get a two tone element strip instead. Guild recruits: five per journey from the recruit pool, one unlocking in each town.']],
 ['Beta v0.11.7',['The Tidegrave lighthouse is a proper narrow tower in HD-2D (it was stretched into a striped box).']],
 ['Beta v0.11.6',['The boss bar stays hidden from the first frame of a boss fight, so the stage no longer shifts as the fight opens.']],
 ['Beta v0.11.5',['Fix: tapping the minimap opens the area map and it stays open (it used to close again straight away).']],
 ['Beta v0.11.4',['Tap the minimap to open the area map (the button is gone), and the minimap sits in the top right corner. No boss HP bar across the top. Timed hits are on by default; the tap that answers a ring never clicks a button by accident, and chain moves get the ring too. Start auto, Pause and Speed work while an action plays. Lore in battle is now Guide: a short summary of how battles work, with a link to the full Guides. Expert battle info shows every weakness and resistance. The Tavern is one screen with Pork Chop sandwiches on top, and Pork Chops come first in the Backpack. The Inn asks before you rest at full health, and a night\'s rest can bring a bond talk. Tents make camp (boon and campfire talks). Training team reshuffles. Story Echoes are once only again. Dens, Sanctums and Lairs keep their own names and say what they are the first time you enter. The Tidegrave lighthouse stands up in HD-2D. An unlocked legend always gets its quest.']],
 ['Beta v0.11.3',['Fix for the new realm looks: extra trees, rocks and pools now keep well clear of roads, doors and chests, so no new path squeezes past a chest or prop, and a realm\'s look no longer reads as a Scourge overlay after its boss falls.']],
 ['Beta v0.11.2',['Realms look like themselves (journeys started from now on): Amberglade is a deep canopy forest, Rimewatch a boreal fir forest under snow, Mirefen a marsh of dead trees and murky pools, Cinderhollow the one volcanic realm (black basalt and glowing spires), Ironroot an open mountain realm of scree and firs, Sunspire a desert of dunes and cacti, the Ashen Expanse grey ash wastes with charred trees, the Shattered Sky pale sky isles and the Drowned Crown sunken ruins in dark water. Journeys already under way keep their realms exactly as they were.']],
 ['Beta v0.11.1',['Side caves are now Dens, and every Den ends in a miniboss. In journeys started from now on, each field puts its Den in the first third of the road, its Sanctum in the middle third and the boss lair in the final third (older journeys keep their maps). Finished Dens, Sanctums and lairs get a green checkmark on the area map, the minimap and the world maps. The Journey tab lists every realm you have reached with its quests, bounties, Den, Sanctum and boss, and shows it at 100% once all are done.']],
 ['Beta v0.11.0',['Shops: a Sell junk button in the Smithy and Alchemy Sell tabs sells gear nobody in your roster can use, or that another piece you own beats on every stat (with enough copies for everyone who could wear it). It shows the list and the gold first. Worn gear, Medals, signature and unique pieces never go, and the new lock on each Sell row keeps anything you choose. Story Echoes come back: leave the dungeon and the Echo waits on its rune circle again, so its materials can be farmed (the first win\'s extras stay one time). The Echo Sanctum shows every gate: open ones glow, closed ones are locked and say what opens them, and the four Calamity Echoes have their own crimson row by the door.']],
 ['Beta v0.10.9',['Reactions: back to 28, one per pair of elements, and each pair reacts the same whichever element was primed (Grave from shadow on an earth prime or earth on a shadow prime). Rain now boosts Steam and Conduct both ways. Every skill shows what it is mainly for (Damage, Heal, Buff, Debuff, Cure, Revive, Guard, Taunt or Summon) in battle, on the character sheet and when learned. Reaching a roaming foe before it spots you now reads clearly as a Sneak attack. Six travel skills in Field skills: Haste and Shadowstep (Thieves, wind and shadow heroes), Ward (Priests, light), Lure (Archers and Druids, earth), Lantern (Mages, fire and light) and Marching Song (Bards).']],
 ['Beta v0.10.8',['Fixes: the "?" beside a foe\'s HP bar no longer turns into an empty black box. The quest board only shows "!" when this town has a notice to accept or a quest is ready to claim. Chest gear no longer says "Legendary" (that tier is now Heroic; Legendary is for legend heroes) and quest rewards no longer say "Craft only" unless a recipe makes them. Bard dual arts that buff the party are no longer Detonators. Warriors\' Rend keeps its Bleed again. The new recruit popup shows each hero\'s elements, class and level. The party screen says when you need a town to swap. The skill list no longer lists what a detonator sets off (the foe cards show it), and moves are tagged "⟐ Primer" and "✸ Detonator" in full again (Settings > Skill tags: Full or Symbols).']],
 ['Beta v0.10.7',['Sanctums and Summons: the side fortresses are now Sanctums, and every one ends in a unique guardian. Beat it and it is bound to you: Priests (the Healer class, renamed) can Invoke it in battle. The Priest prays for one turn; on their next turn the guardian takes the field in place of the whole Vanguard for three of its turns, fighting with its own moves, then the Vanguard steps back in as it was (if the guardian is driven off, no more summoning that fight). It costs 30% of the Priest\'s MP, once per Priest per battle, never in the Daily Trial, and auto battle never prays. Monks from level 10 get Spirit Call: two turns of stillness, then a lesser form takes the Monk\'s own place for two turns. Guardians beaten in earlier journeys on this save count.']],
 ['Beta v0.10.6',['Town: the Notice Board keeps Quests and Bounties; Guilds and the Arena live in the Guild Hall (with Recruits and Natures). Two notices from the first town send you there: Sign the guild ledger and First blood in the pit. A notice can only be accepted in the town of its realm (legend quests and the post-journey notices show everywhere; claiming stays open anywhere). The first win of each arena tier awards a Medal, a charm your wayfarers can wear. Guides now has Charts (the element chart and all 56 reactions), Ailments, Boons and Boss gimmicks as their own tabs; Lore keeps the story. Fix: after a fight in a dungeon or on a field, nearby roamers back off instead of starting the next battle at once.']],
 ['Beta v0.10.5',['Combat: every prime now reacts with every other element (56 reactions, all in the Lore guide); warriors, knights and monks learn a detonator first and the other classes a primer first, so reactions start in the first realm; priming a foe again with the same element refreshes the two turns instead of doing nothing. Basic attacks are typed by class: archers shoot (ranged, hardest), mages, healers and bards strike with magic, warriors, monks and thieves hit harder. Natures are now sub-roles: three per class (a tank, a damage and a tempo or support take) with 10 to 15% stat swings and one perk (Bulwark and Sentinel guard for 60%, Berserkers hit 12% harder below half HP, Sages cast for less, Stillwater monks heal more with chi, and so on); new wayfarers start on one, the Guild Hall still rerolls inside the class. Single element wayfarers: their element deals 25% more, they carry 10% more MP and take a quarter less from their own element; Light mastery\'s healing bonus became +15% against undead and shadow foes. Also: the Momentum bar\'s Surge label no longer sticks out of its box.']],
 ['Beta v0.10.4',['Battle clarity: foes now pick who they aim at a turn ahead and the telegraph shows it (an arrow on their intent tag, a ⚔ mark on the hero\'s card); the Guard button glows when the acting hero is about to take a heavy hit before their next turn, and a hero who guards a hit aimed at them moves again sooner. Skill rows show their target type with a coloured edge (red for foes, green for allies, both for heals that burn undead), an expected damage or healing number, the delivery symbol and status symbols in their text; when only one target is valid the skill, item or scan fires at once. New Chain targeting: Thunder Quarrel and Volt Lance start on one foe and may leap from foe to foe. The key weakness marker left the stage and lives on the foe card; hero levels show on every layout; the foe info panel no longer gets cut off on tall phones.']],
 ['Beta v0.10.3',['Map: the World map is now one connected picture of every town and field you have visited, joined at their real gates; tap anywhere you have been and the party walks there map to map, through the gates (tap a dungeon, cave or fortress door to go inside). The old parchment chart is behind its Chart button. The minimap now shows on phones too (smaller, under the area name) with a button that opens the area map. The area map and minimap use clear icons for every service, gate (with the side it faces), chest, stairs, door, boss, lair, cave, fortress and people with something to say, all in the legend.']],
 ['Beta v0.10.2',['Party: a wayfarer met on the road (a fortress cell, a chance meeting, a claimed challenge) now asks where to stand when your six are full: view their full sheet, swap them in for any party member on the spot, or keep them in the reserves. Build Party: pressing the selected Balanced or Fresh mix again gives another take. Equipment: one Equip Best button for the six (the for everyone and reserves buttons are gone; a reserve\'s sheet still has Auto), and Equip this now? only suggests party members. Alchemy: an Equip best charms button on the Charms tab. Skill lists show the ⟐ and ✸ symbols instead of the Primer and Detonator tags.']],
 ['Beta v0.10.1',['Computers: the page now zooms to fill the window (133%, 167% or 200% by screen size; Settings > Screen size to pin it), so the web and Windows versions are no longer phone sized. Keys: N opens the map and K mutes (they used to share N), and Settings > Keys lets you remap every key. Graphics: Flat is the original look, the plain 2D world with the classic menus; HD-2D and HD-2D High are the lit versions. Records > Journey shows account totals across every journey: play time, journeys and clears, battles won, fled and lost, bosses, Daily Trials, steps, gold, level ups, recruits and chests.']],
 ['Beta v0.10.0',['Fixes from the testers: the forward gate is named by its real side and every north or south town gate now has a visible road to it (tapping any cell of a wide gate walks there); touching a roaming foe starts the fight once and at once (it used to restart the battle several times in a row, re-rolling the foes on screen, while the hero could still walk); a tap to walk carries on after a battle on the way; Stop auto always works and auto stops itself when a new arena wave brings foes it is locked for; the fallen earn no XP from goal rewards either; the Switch goal clears for every kind of swap; a party wipe no longer shows the heroes standing again before the Inn; mana items say who got how much; dungeons, caves, fortresses and the Sanctum ignore the weather in their light; the heat haze is gentler; the HD-2D camera no longer drifts at rest (the drift made the scene jump a pixel); no long press vibration on phones; the battle log reads newest first; New Journey and Starting skills on the title and starter screens.']],
 ['Beta v0.9.9',['Fixes: a chest could land on a path tile in some fields (old saves keep its opened state); rain ripples and splashes no longer cover the hero\'s face; dawn, day, dusk and night now blend smoothly in the HD-2D view and in Low graphics fog instead of jumping. Slightly less XP per fight so a journey ends around level 40 again (about 4.75 hours for a typical first run).']],
 ['Beta v0.9.8',['Playing it yourself pays: hand-played wins show their bonus (+52% XP and gold), and using the systems earns a little more (setting off reactions, breaking shields, guarding a telegraphed hit, reaching a Surge, taming). Auto now opens per foe type once you have beaten that foe by hand three times or scanned it; the Auto button says what is left. Tip cards are short invitations ("Primed with Fire: try Mira\'s Gale Burst") and the expert ones wait until you open that system. A Next goals panel on the map points the way: story goals plus small challenges that each pay a reward once.']],
 ['Beta v0.9.7',['Clearer battles: each foe shows its one key weakness (one your party can set up a reaction with, when there is one); tap it for the rest, or turn on Expert battle info in Settings to see everything. Damage types are now Physical, Ranged and Magic (plus Heal against undead), with at most two weaknesses and two resistances shown. Reactions hit harder on screen: a flash, a name banner, a new sound and a camera punch, and the primed badge pulses when your hero can set it off. Cues tell you what to do: Guard! before a telegraphed hit, Interrupt when a foe winds up, Cleanse when a hex stacks.']],
 ['Beta v0.9.6',['Fewer, better fights: random battles are much rarer and fields now have visible roamers (including each realm\'s foe roles) you can choose to fight or sneak up on; fights pay more, so a journey still ends around level 40. Every Scourge and Calamity has its own realm gimmick that it telegraphs a turn ahead (rising tide, lava vents, a lightning rod, a blizzard, broods of adds, a phase change at half health and more) with a clear answer. Tamed companions grow: a second skill after 12 battles and an evolution after 30. New journeys unlock systems realm by realm (reactions and bonds in the second realm, camp and guild missions in the third, the Echoforge in the fourth); saves you already have keep everything.']],
 ['Beta v0.9.5',['Menus simplified: one Notice Board with Quests, Guilds, Bounties and Arena tabs (claimable first), reachable from the board, the Guild Hall and the Menu. Guilds now have three ranks with one line each (nothing you claimed is lost; some perks open sooner). Every gear slot has an Upgrade button that picks the best next step you can afford (equip a spare, buy, forge, temper or Echoforge) with Show all options for tinkerers; the Smithy shows the best upgrade per slot first. Build Party and Equip best come first on the Party and Equipment tabs.']],
 ['Beta v0.9.4',['Momentum is simpler: doing something different fills the gauge, repeating the same move or only attacking drains it. Fill it to get a Surge (heroes deal 15% more and take 10% less); let it run empty and the party is Drained (10% less dealt, 10% more taken) until you mix it up again.']],
 ['Beta v0.9.3',['Battle screen on phones: the action menu has bigger buttons and fills the space under the battle view, with the party and foes below it (scroll down to see them; the commands always show in full on each turn). Phones turned sideways and other short wide screens now get a layout that fits: battle view, log and party on the left, commands with full labels and the foes on the right, nothing cut off. Hero health bars keep their distance from the foes, and heroes in battle are drawn at the same size and pixel look as the foes.']],
 ['Beta v0.9.2',['The Scourge lair is now part of the land: a rock mound of the realm\'s own ground (frozen rock with icicles, basalt with ember cracks, earth and roots, sandstone, wet rock) with a dark cave mouth dug into it, claw gouges, bones, torches, a broken banner of the Scourge and a faint plume of its light; no flat tower or lettering. It still has its own Lair icon on the map and turns gold once relit. Also fixed the HD-2D world lighting: snow fields and other scenes are no longer washed out.']],
 ['Beta v0.9.1',['Title music plays again: the game used to wait for your first tap before starting any sound, and on the title that tap was usually Continue. Sound now starts at launch where the device allows it (the Android and Windows apps after installing the new APK or installer); in a browser the first tap starts it.']],
 ['Beta v0.9.0',['Title screen: the six wayfarers are now drawn like they look in the world, the same size and pixel look as the overworld, so the scene reads as a journey across each realm; every realm has a fuller foreground and the night scenes no longer show a flat dark band.']],
 ['Beta v0.8.9',['Battle screen on the Galaxy Fold: open, the battle view now fills the left side as large as the screen allows, with the foes moving beside the commands when there are few, and no empty space at the bottom. Closed (and other phones), the commands now come right under the battle view with every row on screen, the acting hero\'s HP and MP sit in the command header, and the party cards follow below. The last row is no longer hidden under the phone\'s navigation bar.']],
 ['Beta v0.8.8',['Dungeons now match their battle backdrops: ice caverns with icicles, crystals and frost, volcanic deeps with lava pools and glowing cracks, sea caves with tide pools, root grottos with glowing fungi, crypts, sandstone halls, keeps and astral vaults. Caves get natural cavern walls instead of square rooms. The Scourge lair entrance on the field is now unmistakable: a dark tower with a beacon and the Scourge\'s banner over a skull gate, with its own Lair icon on the map, and it turns gold once the realm is relit.']],
 ['Beta v0.8.7',['Cloud saves between the phone, Windows and the web now keep the newest one: leaving a device saves your progress and uploads it right away, Continue waits a moment for the cloud check (or tap Use this device now), a window left open checks the cloud again when you come back and every minute, and if two devices really differ you choose which to keep (both are kept). Device clocks no longer decide which save is newer. The Windows close fix arrives with the next installer.']],
 ['Beta v0.8.6',['Fog and weather fixed: no more clear boxes around characters in battle (fog banks had hard square edges), and only a hero\'s face is kept clear of weather instead of a whole box. World fog drifts with the ground, darkens at night and thickens with distance. Softer wet floors and heat haze in battle. New title screen: six wayfarers walk together while the realms change behind them (fields, misty forest, snow, desert, volcano, coast, town at dusk, the heights at night), with the compass emblem beside the WAYFARERS wordmark, and all six always fit the window.']],
 ['Beta v0.8.5',['Battle screen fits every phone and the Galaxy Fold open or closed, with no scrolling: Attack, Skills, Items and Guard are always on screen at each turn, the foe list never gets squeezed away, and wide screens put the turn order and party beside the stage. New damage type symbols (slash, blunt, pierce, ranged, magic, heal): foe cards show which damage types each foe is weak to or resists, next to its elements. Fixed the battle start animation showing only the top left corner zoomed in, and foes no longer shift around before the battle starts.']],
 ['Beta v0.8.4',['Secondary roles: every class now has a main role and one or two backup roles, with new skills and gear for them. Bards sing a magic damage song and stronger healing songs, so they can stand in for a mage or healer; Thieves throw stars and kunai that hit flyers; Monks meditate to heal and buff; Warriors can taunt and debuff; Knights rally the party; Mages and Archers hinder foes; Healers bless. New role gear: war hammers, war standards, throwing stars and kunai, prayer beads, wands, censers and lyres, plus six role charms. Build Party counts backup tanks and healers as half a role. Pacing: a bit more encounters and XP and the first Scourges eased, so a first journey ends around level 40 in about 4.5 to 5.5 hours.']],
 ['Beta v0.8.3',['Chests open again: the lid pops with a glint, the open chest stays while you read what you found, then it fades away. The chest and item sounds are softer. The Equipment tab lists only your party (gear your reserves with Equip best: reserves or from their sheet).']],
 ['Beta v0.8.2',['Personal quest rivals whose wayfarer is not in your six now show see through on the map, with a hollow star on the minimap. You can walk through them and they will not fight; talk to one to learn who it waits for (with their portrait). Bring that hero into your party and it stands solid and fights as before. The Quests tab, Guild Hall and What next? say who is needed. Leaving the rewards screen no longer plays a sound (the victory theme is enough).']],
 ['Beta v0.8.1',['Best Party is now Build Party, since it offers several parties. The Training team now takes your lowest level heroes, and only brings a higher one when nobody lower can be the tank or healer (and then the lowest one who can). Areas with flying foes now bring a real ranged attacker, an Archer first: lances and spells only half answer flyers.']],
 ['Beta v0.8.0',['Weather overhaul: rain, storms, snow, blizzards, fog, gales, sandstorms, heat, ashfall, auroras and starfall now come in layers with depth in the world (2D and HD-2D) and in battle: puddles and splashes on wet ground, lightning that lights the scene (gently, never strobing), drifting fog banks that walls hide, settling snow and ash, heat shimmer. Old visuals updated: the Victory crest in the new lettering, a sunlit colosseum for the Arena, and a shaded minimap.']],
 ['Beta v0.7.9',['Wide battle screen (Galaxy Fold open, tablets, desktop): everything now fits without scrolling. Under the stage, the commands sit on top with the foes right below them, and the party sits beside them, Vanguard then Rearguard, one hero per row. Command buttons widen and wrap instead of cutting words, aim tags and foe cards no longer cut off text, and boss fights put the boss bar beside the turn order to save room.']],
 ['Beta v0.7.8',['Every wayfarer now has their own voice when they challenge you on the road: their own opening, a line if you decline, a shout at half health, a line when they lose and join, when you fall and when you run. Bonded heroes in your party answer them, personal quest rivals and the legends get their own lines too, and Guild Hall challengers say their piece.']],
 ['Beta v0.7.7',['Guild missions now count what you already did on this journey, so a mission you have already done can be claimed as soon as you accept it. Detonator hints in the skill list are now just element symbols (hold or hover for the words). No more blue flash when you tap the screen to move.']],
 ['Beta v0.7.6',['Tap to walk: tap a spot you have already explored on the map or minimap and your hero walks there (stops in front of doors and exits, stops on any input or an encounter). Fixed being unable to walk next to the Alchemy door in Hearthholm: bushes, chests and signs hidden behind walls in the HD-2D view still blocked the way. Every map type was swept: nothing invisible blocks you any more, door fronts stay clear, and gaps in building walls are filled.']],
 ['Beta v0.7.5',['Battle: a turn order bar shows who acts next (and where your chosen skill puts you); foes you have studied show what they plan to do next, and they really do it. Detonating a reaction gives the hero back some MP. Swapping a Vanguard hero with a Rearguard hero is free once every 3 turns. A Momentum gauge rewards mixing up your actions (+10% damage, -10% taken in the zone) and overheats if you repeat yourself. Foes now have roles that punish one mistake each: Shieldbearers protect allies until broken, Hexers stack a curse you should cleanse, Chargers wind up a big hit you should Guard, Leeches drain an unguarded Vanguard, Skirmishers punish never swapping. Scourges telegraph a Cataclysm. Timed hits are a new option in Settings (off by default): tap on the ring for +15% damage or 15% less damage taken. Fixed the taming tip flashing on and off over the rewards window.']],
 ['Beta v0.7.4',['New title screen: your wayfarers in their current look around a campfire at dusk on the road to a walled town, lit by the fire, with embers and stars and a new lineup every so often. New Wayfarers wordmark on the title and in the header, and a new compass emblem as the app icon (Android, Windows, browser tab and home screen).']],
 ['Beta v0.7.3',['Tips: each system now explains itself in one short card the first time you really meet it (your first primed foe, first shield, first tame, first Camp Supplies and so on), one at a time, never over faces in battle. Got it closes it, More opens Guides > How it works. What next? lists things you have but have not tried yet. Settings has Tips on or off and Reset tips.']],
 ['Beta v0.7.2',['Pacing: the first realm no longer throws every system at you. Guild missions and Tempering open after the first Scourge falls (a journey that already tempered gear keeps it), the Tamer\'s Stick quest goes up in the second realm, and personal quests open in the third realm. The Rearguard now earns the same XP as the Vanguard, so your six stay about the same level.']],
 ['Beta v0.7.1',['The front three of your party are now the Vanguard (the back three stay the Rearguard). Catch up XP is much bigger for heroes far behind your top wayfarer (+38% at 2 levels, +125% at 5, up to +300% at 10 or more), so swapping heroes in pays off fast. Auto battle and Run are now remembered between plays and updates. Quest lists put quests you can claim first, then active ones. After Best Party, Equip best gear shows as done once used.']],
 ['Beta v0.7.0',['Battle screen rehaul: HP plates, element badges, status rows and damage numbers are laid out so none sit on a face or on each other; the last log line sits under the stage; commands are grouped (Attack, Skills, Items, Guard / Scan, Lore, Switch, Flee / Auto); the active hero is framed in gold and cards are more compact. The battle start flash now covers the whole screen instead of one corner. Detonators: while aiming, the foes they will set off glow with a ring and a tag naming the reaction, and the reaction floats over the foe when it fires.']],
 ['Beta v0.6.9',['Shops and menus reorganised: every shop has Shop and Craft tabs with All plus sections (Alchemy now has its own Charms section), every filter is a dropdown with new options (for one hero, rarity, upgrades only, can afford, cheapest first), and the Menu is grouped as Party, Backpack, Quests, Map, Records, Guides and Settings. Fixed text cut off at the bottom of menus on phones with a browser bar (Fold Tempering).']],
 ['Beta v0.6.8',['World: fortresses stand up as real gatehouses in the HD-2D view; leaves, butterflies, snow and other drifting effects now stay in the world instead of sliding with the screen; nothing hovers over the hero\'s face any more (fixed the white and pink boxes left over in parts of the screen); opened chests disappear; the world map is now a parchment chart with little pictures of each town, field, dungeon, cave and fortress, roads between them and a pin for your party; side fortresses are just called fortresses.']],
 ['Beta v0.6.7',['Capes no longer show on hero sprites (they keep their stats); only weapons and personal quest rewards change how a hero looks. Every item now has its own icon: each weapon, armor and cape changes shape as its tier rises (gems, gold trim, a glint, a glow), every charm has its own pendant, and materials have icons too. The three legendary signature weapons got their names back.']],
 ['Beta v0.6.6',['Daily Trial weekly twist: each week brings one rule change for the trial (this week: Weak spots hurt more), shown on the entry screen and as a chip in its battles; the trial stays the same for everyone on the same day. New Game+ modifiers: when starting a new cycle you may pick up to two (Foes hit harder, Cold inns, Elites everywhere, Reactions only, Ironman), each trading risk for more XP or gold.']],
 ['Beta v0.6.5',['Taming log: Records > Bestiary shows Tamed X of Y, where seen foes roam, and silhouettes for the ones you have not met. Bond goals: hero sheets and a new Bonds page show how many wins side by side until the next campfire talk or joint tech, with a notice when a talk is ready. Make camp (from the third realm, Camp Supplies at Alchemy): rest in the field for a small heal and pick one boon for the next 3 battles, then listen to ready campfire talks.']],
 ['Beta v0.6.4',['Names: heroes outside your party are now your Reserves, and the back three of the party are the Rearguard. The button is now Equip best: reserves.']],
 ['Beta v0.6.3',['Best Party now offers several formations (Balanced, Boss ready, Fresh mix) chosen for role balance over raw level and gear, plus a Training team that brings lagging heroes along with a strong tank and healer. Catch up XP now measures against the highest level hero on your whole roster. New Equip best: at camp fills out heroes outside the party from spare gear without touching the party. Legendary tags are now only for heroes with legend quests (Kaevan, Nikaris, Jaeson); other rare heroes show Epic.']],
 ['Beta v0.6.2',['Characters now belong to the HD-2D world and battle scenes: they take the light around them (sunlight, moonlight, a torch at their side, lava glow, spells), the scene\'s colour grade, fog in the distance and a soft rim light, and stand on a soft shadow instead of a hard dark bar. In the world they are drawn at a size that fits the rooms and streets. Fixed a pale line under the hero and tinted boxes around glows and shadows.']],
 ['Beta v0.6.1',['A clearer victory screen. A beaten foe you can tame now comes first, and pressing Continue without deciding asks whether to tame it or leave it behind. Gold, experience, materials and finds sit in a compact grid, and every hero in the fight shows the experience they gained, their catch up bonus, and any level up with points to spend. Wayfarers met on the road or won in a duel are no longer labelled Legendary; that label is kept for the legendary heroes. The save note no longer sits on the logo while a window is open.']],
 ['Beta v0.6.0',['A simpler title screen: Continue comes first when you have a journey, then New journey and the Daily Trial; Settings and Help sit in a small row, and Import, Recover and Redeem are grouped under Saves and codes. No more export reminder after every update: your saves are kept on your account, and Export is still in the Journey tab. Titles, banners and labels now use clean, smooth lettering instead of the pixel font, so numbers like 5 and S no longer look alike. Choosing a target no longer draws a box: the foes you can pick glow, with their name and a small hint above them.']],
 ['Beta v0.5.9',['A primed foe now shows a small floating element badge with the turns left, in place of the large PRIMED chip and the glowing sphere; tap it for the full explanation, which is also on the foe card. The HD-2D world keeps much more of the screen in focus: the sharp band around your party is wider, the blur is gentler, and the near side of the view stays almost sharp.']],
 ['Beta v0.5.8',['Fix: on the battle stage, a fighter standing in front no longer covers another fighter\'s element badge or HP bar, and falling rain and snow no longer hide them. Bars, shield pips and element badges now always draw on top.']],
 ['Beta v0.5.7',['Fix: heroes, townsfolk and monsters in the HD-2D world no longer look sliced and smeared; they now show with their full detail.']],
 ['Beta v0.5.6',['The world is now a lit diorama on Medium and High graphics: a tilted camera follows your party over maps where walls, cliffs and houses rise from the ground with gabled roofs and lit windows, props stand upright, water sits low and lava glows. Lamps, torches, windows, braziers and crystals light the ground around them, the sun casts soft shadows, fog gathers in the distance, and bloom, a tilt-shift focus band, light shafts and colour grading follow the time of day and the weather. Anything that stands in front of your hero thins out so you never lose sight of them. Settings > HD-2D world turns it off; Low and devices without WebGL keep the classic view.']],
 ['Beta v0.5.5',['Battles take place on lit, dioramic stages: a perspective floor that is sharp where the fighters stand and softens toward the horizon, a blurred background with glowing highlights, torches, braziers, lava and moonlight that light the ground, soft shadows, a colour grade that follows the time of day and the weather, and boss stages with braziers and a glowing rune circle. Every element has its own spell effect with light (fire tongues, shattering ice, a lightning bolt from the sky, a water geyser, earth spikes, a wind funnel, a beam of light, a shadow vortex), and Limit Breaks get a spotlight. Medium keeps the frame rate of before; High lights the fighters too; Low and devices without WebGL keep the classic stage.']],
 ['Beta v0.5.4',['Heroes, townsfolk and monsters are drawn at twice the detail: smoother outlines, six step shading with light from above, rim light, catchlights in the eyes, sheen on hair and metal, folds in cloth and textured fur, plates and feathers on monsters. Heroes stand a little taller. On the Low graphics setting the world and battle views keep their old resolution so slower phones stay smooth.']],
 ['Beta v0.5.3',['A new look for menus and screens: night blue panels with gold borders and corner ornaments, a gold tab strip for the menu groups, a battle command menu with a lit cursor, framed portraits, glossy bars, a framed title screen and a grander Victory screen. Every button and tab is now at least 40 pixels tall on touch screens, text contrast is checked on every main screen, and reduced motion turns the transitions off.']],
 ['Beta v0.5.2',['Fix: on a Galaxy Z Fold opened (and any screen where the map view comes out exactly 300 pixels wide) the map no longer shrinks to a small box after a battle.']],
 ['Beta v0.5.1',['A graphics upgrade: soft light from lamps, windows, torches and spells, shading and depth, water that glints, grass that sways, leaves, dust, birds and critters, a battle camera that pushes in on big hits, richer element effects and victory hops. Settings has a Graphics option (Auto, Low, Medium, High); Auto picks what your device runs smoothly, and reduced motion keeps everything still.',
  'A Quest Board quest or Guild mission that is ready to hand in is announced, and the Menu button and Quests tab show how many are waiting. New skills are listed first on the victory screen. Status symbols sit under the name in the Party menu. Tempering explains close choices and opens faster with a full pack.',
  'The Android app now picks up every update, including fixes that keep the same version number, and never goes back to an older version. The website offers the same.',
  'Fixes: the map view no longer stays small after a battle on foldables and wide phones; a beaten Mimic no longer comes back when its chest had been moved off a path; hints during a battle no longer cover the shield pips on foe cards; townsfolk no longer stand on a path after a town gate was cleared.']],
 ['Beta v0.5.0',['The game is now called Wayfarers (Beta).',
  'Fixes: the tavern no longer runs out of room in an area (four seats, a shuffle and your gold are the only limits); the map view keeps its size after battles on wide phones and when you rotate; stairs, chests, levers, props and townsfolk never stand on a corridor, road or doorway in any map, and old saves tidy themselves when a map loads; the battle menu always has a Back button; every shop screen has a back arrow; the minimap shows in every field, town, dungeon, cave and fortress; the Inn offers a bed for your wayfarers; status effects show as symbols that fit their boxes; Tempering lists what you can temper now first.',
  'Battles stand on solid ground that matches where the fight began, flying foes hover with a shadow, and bosses get their own stages. Touch a roaming foe before it sees you for a Surprise round. Gathering spots sit beside the trees, rocks, grass and water they come from. Town gates have a clear lane. Dungeon entrances look different from realm to realm. The first realm has single type wayfarers and monsters only (bosses and elites aside), and short hints that use your own party (Settings can turn them off, Guides keeps them).',
  'Shops put the best upgrades for your party first and explain close calls. The Smithy can buy, forge and equip the best gear for the whole party in one go, with a plan to confirm and Undo. Best Party reads delivery types, legal weapons and the Bestiary, says why it picked each hero, and can equip them straight away. Party and boss screens show what the team is missing and how ready it is. Holy Water can reapply itself. Items stack to 50. The first boss gives two Pork Chop Sandwiches; in a dungeon, eat two to walk back to town.',
  'Personal quests open after 40 battles together in the second realm, with no level needed. Factions are now Guilds, reachable from the Guild Hall. Heroes below the top level catch up with bonus XP. After a Scourge falls, its lingering energy tells you the Echo waits.',
  'Settings: Master, Music and Sound effect volumes with mutes. Cloud saves sync on their own. Day turns to dusk and weather changes over a few seconds instead of at once. A Save button sits in the menu header, and a small Saving / Saved note shows when the game saves.']],
 ['Beta v0.4.6',['The Android app now updates itself: it downloads each new version in the background and starts it the next time you open the game, or straight away with Restart now. Saves and sign in stay as they are. If a new version ever fails to start, the app goes back to the version it was installed with.']],
 ['Beta v0.4.5',['A full orchestral soundtrack: every track is composed around one theme, the Meridian, with strings, harp, woodwinds, brass, choir, organ and orchestral percussion. Towns and fields change with day and night, every tileset has its own field arrangement, Calamity realms get their own, and a relit realm plays brighter.','Battles, elites, Scourges and the three phase Calamity fight each have their own music. A tension layer comes in when someone is under 30% HP, boss phases add a layer, and roamers chasing you in a dungeon raise the tension too. After a normal battle the field music picks up where it left off.','Jingles for level ups, recruits, quests, faction ranks, items, inn rests and relit beacons.','New sound effects for every weapon family, element, hit, heal, buff, debuff, Limit Break, summon, boss phase and menu, plus quiet footsteps on Mid or High.','Ambience: wind, birds, crickets, waves, rain and thunder, drips, a town murmur, embers and a Calamity hum. Settings > Ambience, quiet by default.','Settings: Music style (Orchestral or Classic chiptune) and Credits. Records > Music Room plays every track you have heard.']],
 ['Beta v0.4.3',['Capes: a fourth equipment slot for every class, sold at the Smithy beside armor and shown on your hero. Boss fights were re-tuned around them.','Before you play on a new version, the game offers to export your saves as a backup.','Fallen heroes earn no XP. Wins mostly on auto pay 66% XP and gold, and auto deals 85% damage. Random battles are a little rarer at every setting and never come within 8 steps of the last one.','After a boss you stay in the dungeon; its Echo appears once you have left and come back. A big boss HP bar runs along the top of boss and miniboss fights. Echoes pay a little more.','Every wayfarer has a rival of their own. Twenty new minibosses, dealt out so a journey rarely meets the same one twice. Travel packs from traders roll their contents.','Tempering lists only what can still be tempered, rarest first. Detonator skills say which primes they set off. The Tamer\'s Stick measures against the Bestiary as listed.','Much easier early game: regular foes are softer in every realm and much softer in the first two, there are no pack tactics in the first two realms, heroes recover more HP after each win early on, the world grows tougher only half as fast in the field, and the first two Scourges hit less hard. You begin with 400 gold, gold drops are up and shop prices down. Auto now deals 85% damage and pays 66%.','Twenty-four starters (three per class, three per element) for many more starting draws. Beat a wayfarer in a duel and they wait for you at the tavern. Accept all and Claim all buttons on the Quest Board, bounties and faction missions. Back to the main menu from Settings. The Inn closes after you rest. Town gates always meet a road with nothing in the way.','Fixes: Space at the Inn no longer puts you straight to bed, and the fortress gatehouse no longer covers your hero. Personal rewards, fortress charms and The Steady Hand charm re-tuned.']],
 ['Beta v0.4.1',['Fix and rebalance pass. Fixes: challenge fights no longer freeze, mimics and props never block paths, shield pips and draw order fixed, indoor maps ignore weather, dungeon entrances and levers placed properly, fewer east exits, map back button, latest input wins, auto settings saved, Records opens on Journey.','Rules: fallen heroes stay down until revived; Poison, Curse and boss Wounds last past the fight; weapon types rebalanced against beast and armored foes; Auto is banned in elite, miniboss and challenge fights and plays simpler; parties can be smaller than six; Lore in the battle menu; weather and time tags always visible; weather now falls in towns too.','Balance: tougher packs, bosses scale toward your party level and grow with every boss defeated, echo levels follow your party, small parties face softer foes, gold and XP trimmed and prices raised.','World: sixteen realms (twelve standard, four Calamity realms), each with its own look, monsters, weather, townsfolk and quests. A living Scourge or Calamity changes its realm until it falls. Visible foes roam the dungeons, side fortresses join the side caves, and most caves and fortresses end in a miniboss. Dusk and dawn look new.','Also: wayfarer challenge wording, start with one to three wayfarers, Gear menu is now Backpack, shop and craft lists sort by rarity with filters, Craft only tag, a dynamic title screen, NPCs with more to say, a sixth faction (The Steady Hand), personal quest rewards in three slots, and new item sprites.']],
 ['Beta v0.4.0',['Bug fixes: tapping or clicking a foe now targets it (touch, mouse, keys, pad), field skills that need a target work, shield pips have their own spot, the party stops walking the moment a battle starts, dungeon stairs never block the route, and Auto reads Start auto or Stop auto.',
  'Battle: tap a rearguard hero to switch, Auto settings live in the menu as well as in battle, Undead take damage from healing, and foes have archetypes (Flying, Armored, Jelly, Swarm, Beast and more) that skills and weapons answer by delivery (Slash, Blunt, Piercing, Ranged, Magic, Heal).',
  'Menus: seven top groups with sub tabs, Forge is the new name for making gear, recipes you can make now come first, purchase animations, Pork Chop Sandwich leads back to the last town, longer dusk and dawn with their own look, starter sheets, Legacy heroes count toward the three starters, and item strength borders with tier pips.',
  'Wayfarers: 64 single type wayfarers (every class in every element), a signature skill for every wayfarer, and a new starter draw of 8 options from a pool of 16.',
  'World: one long winding field between towns, gates facing north, south, east and west with matching landings, a world map screen, and optional side caves with a special reward (a +2 piece of gear, a rare item, a challenge wayfarer or a unique charm). Old journeys keep their old maps.',
  'Dungeons: about twice as big with side branches and dead ends, the lever is far from the entrance and opens the key room, then the key opens the boss door. Required route is about 16 to 20 minutes per main dungeon.',
  'Weather: snow looks frosty on phones, and rare skies appear a few percent of the time: Blood Moon, Solar Eclipse, Meteor Shower and an Elemental Surge for every realm, each with fair effects both sides feel. The Daily Trial never uses them.',
  'Chance encounters: about once per 200 steps on roads and in caves you may meet a wayfarer who needs a potion, is being ambushed, challenges you to a duel, or trades. Helping, winning or hiring brings them into your roster without using the tavern cap, and every wayfarer you meet is logged in the Codex.',
  'Factions: Wayfarers\' Guild, Smiths\' Union, Alchemists\' Circle, Beastwardens and Archivists, six ranks each, missions in Guides and Records, modest perks and a unique charm per faction. Per journey only; your best rank is kept as a title.',
  'Under the hood: all tunable numbers live in config.js, data tables are split into their own files, dead code is gone, and fog is drawn from a cached sprite.']],
 ['Beta v0.3.5',['Wayfarers: wanderers are now called wayfarers everywhere. Each journey draws its own seeded subset of about 30 from a roster of 60+, always including anyone you already own; the Codex still tracks every wayfarer ever seen on your account.',
  'Taverns: at most 4 offers, hiring leaves an empty seat until the next shuffle, shuffles only after an inn rest or a stage clear (with a cooldown shown on screen), each town has its own pool and a limited number of tavern recruits before you move on.',
  'Natures: every wayfarer rolls one nature from a small pool that suits its class and personality. The Guild Hall Nature service rerolls within the pool or lets you pick one.',
  'Type chart revamp: elements no longer resist themselves by default; every element now has real strengths and counters. Primers, detonators and reactions work as before.',
  'Battle clarity: a loud Primed status (pulsing aura, chip with element and turns left, sound, target highlights), one new element icon set used everywhere, a purple Limit Break bar, and a legendary stamp on every Legendary hero.',
  'Starting party: you may begin with one, two or three wayfarers. The game asks you to confirm a smaller start, and you can recruit more in any tavern. Fewer heroes means a harder early game, and big bosses grow tougher for every hero short of six.',
  'Weapons and armor: each class uses 2 or 3 weapon types, each with its own perk (cleave, charge, crush, flurry, long draw, discord, soothe, tempo and more), new Monk knuckle and claw lines and Bard lute, harp and flute lines. Armor is Light, Medium or Heavy and only the matching classes wear it. Gear a hero can no longer use goes to your pack, never deleted, with a message.',
  'World: every town, field and dungeon takes its mood from the Scourge or Calamity at the end of the stage, with no spoilers. New journeys get two fields per town (the dungeon waits in the second), bigger fields with side trails and shortcuts, and bigger dungeons with loops. Journeys started on an older build keep their original map shape.',
  'Map and UI: clear icons and a legend for the Smithy, Alchemy, Inn, Tavern, Guild Hall, quest board, waystone, gates and dungeon entrances; the roster and party screens no longer overlap; the battle rewards Continue button stays in view; town props no longer float.']],
 ['Beta v0.3.4',['Save safety: a save that cannot be read is never replaced or hidden. You get a clear message with Retry and Export, and the raw data stays exactly as it was.',
  'Backups: before a version migration, an overwrite, a cleared slot, an import, a restore or a cloud pull, the old save is copied to a rolling backup (last 3 per slot).',
  'Recover Saves (title screen): finds every save, backup and stray slot on this device and in your account, shows heroes, progress and times, and restores any of them into a slot you pick.',
  'Export and Import: every slot exports as a code or a file, and imports check the save and ask before replacing anything. Use it to move a journey between devices or links.',
  'Account saves: signed in players get cloud saves per slot with the last three versions kept, background sync, a sync icon, Sync in the Journey tab, and a choice when this device and your account differ. Visitors stay local with an Export reminder.',
  'Saving to this device now tells you when it fails instead of failing silently.']],
 ['Beta v0.3.3',['Bug fixes: the party can no longer walk through town buildings, heroes no longer look like they stand on roofs, the Smithy cannot get stuck on a failed redraw, and the battle scene keeps a fixed shape on wide phones instead of stretching.',
  'Battle screen: every hero and foe card shows name, level, element symbols (a distinct shape per element), HP and MP bars with numbers, and a status row that is never covered. Tap or click any unit for a full detail panel.',
  'Equipment: Auto best gear (party) may take from heroes outside the party, Equip best for everyone balances the roster, and the per-hero Auto never takes from anyone. All of them handle companions and show a summary with Undo. "Best for" now lists every party member an item helps, ranked, with stat arrows.',
  'Party tools: team loadouts (8 slots), a Best Party suggestion, field skills (heals, cures, revives outside battle), XP to next level bars, sorting and filters for Party, Roster and Codex, and the Guild Hall no longer handles the party.',
  'Town: the Inn opens on Rest with no scrolling. Bonds and campfire scenes moved to each hero\'s sheet. Tap the weather or day and night tag to see what it does here.',
  'Endgame: the Echo Sanctum, a hall of sixteen Echo gates, replaces the Echo Rift once all five story Echoes are beaten.',
  'Offline: the game is fully self contained and keeps playing and saving with no connection. Bestiary, Codex and report writes queue and sync safely when you are back online.']],
 ['Beta v0.3.2',['Battle text is smaller and floats over the unit it affects, stacked so nothing overlaps, and stays up longer. The top banner is now a thin strip for big moments only.',
  'New skill notices: "<Hero> learned <Skill>!" on the battle results and as a small toast in the world, with a New badge on the hero sheet.',
  'Companions show their exact bonuses, and every monster family adds a small perk (crit, speed, ailment ward, thorns or mending).',
  'Leveling is about 15% slower. Battles won mostly on auto pay 66% XP and gold (drops unchanged). Auto is locked on a boss until you beat that exact fight by hand once.',
  'Echoes reworked: beat a Scourge or the Calamity and an optional Echo of it lingers in its dungeon. Beat all five and every Echo in Aurelis unlocks for your account. The Echo Rift at any waystone opens after the Calamity.',
  'New: Echo Shards and Echo Essence, and six Echoforged weapons at the Smithy.',
  'New: a full map and a minimap with fog of war (Map button, N, or Y on a pad).',
  'Animation pass: swings, thrusts, bow draws, dashes, casts, songs and channels; foe telegraphs; boss phase flourishes; summon entrances. A Motion setting trims it all to simple flashes.']],
 ['Beta v0.3.1',['Fixed: the Arena could not be challenged. Fixed: the Party Sheet button. Menus and the gear picker keep their scroll and focus when you spend a stat point.',
  'Party rows now show portrait, level, class, HP and MP bars with numbers, elements and a KO or status marker. The battle log lists newest first, status icons never overlap, and floating numbers stay up longer.',
  'Auto battle can now switch heroes in and out (with a short cooldown, shown in the banner). Resting at the inn fades out with a rest chime.',
  'Towns: every building has its own roof color, shape and props, with big signs, and the quest board has a marker.',
  'New: an Equipment menu, Auto best gear with undo, an optional Auto equip new gear setting, and Best for tags with an Equip this now? prompt after buying, crafting or winning gear.',
  'New: Tomes for mages, the Faith stat for healers and chroniclers, and descriptions for every stat and class.',
  "New: the Tamer's Stick. It grows stronger with every Bestiary entry and starts to glow; a Guild Hall quest hands it over.",
  'New: day and night. Time moves as you walk and fight; at night some field foes change and all are a bit tougher. The inn sets it to morning, tents pass some time.',
  'Weather now lasts a while, follows you between a realm\'s town and field, and is clear most of the time.',
  'New: Mimics hide in some dungeon chests. Watch for a wiggle and a red glint.',
  'Tamed monsters are now Companions: pair one with each hero for a bonus, and Summon it once per battle for 3 turns. Old saves convert automatically and return their gear.',
  'Guild Hall challenges now rotate after an inn rest or a cleared Scourge, with four new heroes to earn. Accepted challenges stay posted.']],
 ['Beta v0.3.0',['Fixed: dungeons could trap you when the lost wayfarer stood in the only corridor. Every dungeon is now checked when it is built (key before the boss door, lever before the vault, every chest, the stairs), and decor never sits on or beside the way forward. Saves stuck today are freed when you load.',
  'New: a Stuck? button in the menu while you are in a dungeon. It walks the party back to the entrance for free.',
  'Limit Breaks open at level 15 for every hero, with no other condition. Limit I is a lighter version; at level 30 it becomes Limit II, a new and stronger move.',
  'The level cap is 50. A normal journey ends around level 38 to 42; levels past 40 come from New Game+, Nightmare Echoes, the new Eclipse Gauntlet arena tier and the Calamity rematch.',
  'Every class and Legendary hero learns two new skills in the 40s and a level 50 capstone.',
  'New Game+ foes gain 3 levels per cycle. The Calamity and the Nightmare Echoes rise to meet a party above level 40.']],
 ['Beta v0.2.0',['Battles are easier to read: damage numbers by type, a scrollable battle log, and status icons you can tap for details.',
  'Matchups show on every target before you strike (Weak, Neutral, Resists, Immune). Hidden quirks and Scourges stay a mystery until you hit or scan them.',
  'The Bestiary grows with you: Seen, Studied and Mastered entries, plus small permanent perks for hunting the same foe.',
  'Every popup has a back arrow next to the X. Party swapping is now tap one hero, tap another.',
  'The Forge is now Tempering: each upgrade needs ore or logs, a monster part and a realm relic. Buy what you are missing right there.',
  'Skills arrive about every 3 levels. Limit Breaks open at level 15 and personal quests at level 20, both after the second town. Skills you already learned stay learned.',
  'Dungeon entrances sit further from the town gate.',
  'The Journey tab has a pinned Save button, Scourge progress, and new stats including steps walked.']],
 ['Beta v0.1.0',['The Smithy now handles every weapon and armor need: buying, selling, forging, crafting gear, and ore, wood and monster parts.',
  'The Workshop is now Alchemy: potions, tonics, charms, Holy Water and tents, plus herbs and brewing.',
  'New: Pork Chop Sandwich (tavern). A sure escape in ordinary fights, or a quick walk back to a dungeon\'s entrance.',
  'New: Holy Water (Alchemy). Keeps random battles away for about 150 steps.',
  'New: Tent (Alchemy, or craft one). Rest in the wild for 60% HP and MP. Pick your campsite carefully.',
  'Version numbering restarts at Beta v0.1.0. Your saves carry over untouched.']]
];
// =================== ELEMENTS ===================
const EL={fire:'Fire',water:'Water',earth:'Earth',wind:'Wind',lightning:'Lightning',ice:'Ice',light:'Light',shadow:'Shadow'};
const ELK=Object.keys(EL);
const ELC={fire:'#e8553a',water:'#3f8fe0',earth:'#b08a4a',wind:'#5fc9a0',lightning:'#f2c93a',ice:'#8fdcf0',light:'#f6e7a8',shadow:'#9a6ae0'};
// Matchup chart (v0.3.5 revamp): attacker -> {strong: x2, resisted: x0.5}. No immunities.
// Self matchups are no longer automatic. Only Fire, Ice and Shadow resist themselves (flame cannot burn flame, frost cannot chill frost, dark
// cannot darken dark). Water, Earth, Wind and Light take neutral damage from their own element. Lightning is WEAK to itself (it arcs through
// a conductor). Light is the glass element (no resistances) and Earth, Ice and Water are the sturdy ones.
const CHART_DEF={
 fire:{s:['ice','shadow'],r:['fire','water','earth']},
 water:{s:['fire','earth'],r:['ice','shadow']},
 earth:{s:['lightning','fire'],r:['wind','water']},
 wind:{s:['earth','fire'],r:['lightning','ice']},
 lightning:{s:['water','wind','light','lightning'],r:['earth']},
 ice:{s:['wind','water','earth'],r:['ice','fire']},
 light:{s:['shadow','ice'],r:['fire','lightning']},
 shadow:{s:['light','lightning'],r:['shadow','water']}
};
const CHART={};ELK.forEach(a=>{CHART[a]={};ELK.forEach(d=>{CHART[a][d]=CHART_DEF[a].s.includes(d)?2:CHART_DEF[a].r.includes(d)?.5:1;});});
// Dual-type defenders: matchups combine on a soft curve so nothing reaches x4.
// both weak -> x2.5, weak+neutral -> x2, weak+resist -> x1, resist+neutral -> x0.5, both resist -> x0.35
const DUAL_MAP={4:2.5,2:2,1:1,.5:.5,.25:.35};
const CAP_GUARDED=2;   // Scourges, Calamities and heroes never take more than x2 from matchups
function matchup(atkEl,defEls){
  if(!atkEl)return 1;
  const ms=defEls.map(d=>CHART[atkEl][d]);
  if(ms.length===1)return ms[0];
  const p=Math.round(ms[0]*ms[1]*100)/100;
  return DUAL_MAP[p]!==undefined?DUAL_MAP[p]:p;
}
